// FASE 2: formatacao do layout largo v3
const D = 700000001;
function hex(h){ return { red: parseInt(h.slice(0,2),16)/255, green: parseInt(h.slice(2,4),16)/255, blue: parseInt(h.slice(4,6),16)/255 }; }
const petrol = hex('0E3A34'), paper = hex('F2F8F6'), mist = hex('E2EFEA'), teal = hex('0C7C66'), muted = hex('5C6F6B');
const band1 = hex('FAFDFC'), band2 = hex('F1F7F5'), line = hex('C9DED8');
const redBg = hex('FCE8E6'), red = hex('C5221F'), ambBg = hex('FEF3E0'), amb = hex('B26A00'), green = hex('1E8E3E'), ambHdr = hex('FBF0DA');
function rng(r1,r2,c1,c2){ return { sheetId: D, startRowIndex: r1, endRowIndex: r2, startColumnIndex: c1, endColumnIndex: c2 }; }
function fmt(range, format, fields){ return { repeatCell: { range: range, cell: { userEnteredFormat: format }, fields: 'userEnteredFormat(' + fields + ')' } }; }
function merge(r){ return { mergeCells: { range: r, mergeType: 'MERGE_ALL' } }; }
function colw(i, px){ return { updateDimensionProperties: { range: { sheetId: D, dimension: 'COLUMNS', startIndex: i, endIndex: i + 1 }, properties: { pixelSize: px }, fields: 'pixelSize' } }; }
function band(r){ return { addBanding: { bandedRange: { range: r, rowProperties: { firstBandColor: band1, secondBandColor: band2 } } } }; }
function cond(ranges, type, val, format, i){ return { addConditionalFormatRule: { rule: { ranges: ranges, booleanRule: { condition: { type: type, values: [{ userEnteredValue: val }] }, format: format } }, index: i } }; }
const q = [];
// titulo
q.push(merge(rng(0,1,0,19)));
q.push(fmt(rng(0,1,0,19), { backgroundColor: petrol, verticalAlignment: 'MIDDLE', textFormat: { foregroundColor: paper, bold: true, fontSize: 15 } }, 'backgroundColor,verticalAlignment,textFormat'));
q.push({ updateDimensionProperties: { range: { sheetId: D, dimension: 'ROWS', startIndex: 0, endIndex: 1 }, properties: { pixelSize: 46 }, fields: 'pixelSize' } });
// linha 2 filtros
q.push(fmt(rng(1,2,0,3), { textFormat: { foregroundColor: muted, fontSize: 9 } }, 'textFormat'));
q.push(fmt(rng(1,2,3,4), { backgroundColor: ambHdr, textFormat: { foregroundColor: petrol, bold: true, fontSize: 10 }, horizontalAlignment: 'CENTER' }, 'backgroundColor,textFormat,horizontalAlignment'));
q.push(fmt(rng(1,2,4,5), { textFormat: { foregroundColor: teal, bold: true, fontSize: 10 } }, 'textFormat'));
// secoes (merge + estilo)
const secs = [rng(3,4,0,6), rng(3,4,7,13), rng(3,4,14,19), rng(8,9,0,6), rng(14,15,7,13), rng(14,15,14,19), rng(16,17,0,6), rng(22,23,0,6)];
for (const s of secs) { q.push(merge(s)); q.push(fmt(s, { backgroundColor: mist, textFormat: { foregroundColor: petrol, bold: true, fontSize: 10 } }, 'backgroundColor,textFormat')); }
// headers de lista
const hdrs = [rng(4,5,7,13), rng(4,5,14,16), rng(9,10,0,4), rng(15,16,7,13), rng(16,17,14,19)];
for (const h of hdrs) { q.push(fmt(h, { textFormat: { foregroundColor: petrol, bold: true, fontSize: 9 } }, 'textFormat')); q.push({ updateBorders: { range: h, bottom: { style: 'SOLID', color: line } } }); }
// KPIs
q.push(fmt(rng(4,5,1,2), { textFormat: { foregroundColor: petrol, bold: true, fontSize: 16 } }, 'textFormat'));
q.push(fmt(rng(4,5,3,4), { textFormat: { foregroundColor: petrol, bold: true, fontSize: 12 } }, 'textFormat'));
q.push(fmt(rng(4,5,5,6), { textFormat: { foregroundColor: petrol, bold: true, fontSize: 12 } }, 'textFormat'));
q.push(fmt(rng(6,7,1,2), { textFormat: { foregroundColor: petrol, bold: true, fontSize: 12 } }, 'textFormat'));
q.push(fmt(rng(6,7,3,4), { textFormat: { foregroundColor: petrol, bold: true, fontSize: 12 } }, 'textFormat'));
// barra progresso
q.push(merge(rng(5,6,1,6)));
q.push(fmt(rng(5,6,1,6), { textFormat: { foregroundColor: teal, fontSize: 12, fontFamily: 'Roboto Mono' } }, 'textFormat'));
// equipe ritmo + listas 9pt
q.push(fmt(rng(10,15,3,4), { textFormat: { foregroundColor: teal, fontSize: 9, fontFamily: 'Roboto Mono' } }, 'textFormat'));
q.push(fmt(rng(5,13,7,13), { textFormat: { fontSize: 9 } }, 'textFormat.fontSize'));
q.push(fmt(rng(16,26,7,13), { textFormat: { fontSize: 9 } }, 'textFormat.fontSize'));
q.push(fmt(rng(17,27,14,19), { textFormat: { fontSize: 9 } }, 'textFormat.fontSize'));
q.push(fmt(rng(4,5,7,13), { textFormat: { foregroundColor: petrol, bold: true, fontSize: 9 } }, 'textFormat'));
// esteira valores bold
q.push(fmt(rng(5,13,15,16), { textFormat: { foregroundColor: petrol, bold: true } }, 'textFormat'));
// funil e retornos
q.push(fmt(rng(17,21,1,2), { textFormat: { foregroundColor: petrol, bold: true, fontSize: 11 } }, 'textFormat'));
q.push(fmt(rng(18,21,3,4), { textFormat: { foregroundColor: muted } }, 'textFormat'));
q.push(fmt(rng(23,24,1,2), { textFormat: { foregroundColor: petrol, bold: true, fontSize: 11 } }, 'textFormat'));
q.push(fmt(rng(23,24,3,4), { textFormat: { foregroundColor: petrol, bold: true, fontSize: 11 } }, 'textFormat'));
// filtro etapa P16 destaque
q.push(fmt(rng(15,16,15,16), { backgroundColor: ambHdr, textFormat: { foregroundColor: petrol, bold: true }, horizontalAlignment: 'CENTER' }, 'backgroundColor,textFormat,horizontalAlignment'));
// banding
q.push(band(rng(10,15,0,6)));
q.push(band(rng(5,13,7,13)));
q.push(band(rng(16,26,7,13)));
q.push(band(rng(17,27,14,19)));
// condicionais
const st = [rng(6,7,5,6), rng(23,24,5,6)];
q.push(cond(st, 'TEXT_CONTAINS', '✖', { backgroundColor: redBg, textFormat: { foregroundColor: red, bold: true } }, 0));
q.push(cond(st, 'TEXT_CONTAINS', '⚠', { backgroundColor: ambBg, textFormat: { foregroundColor: amb, bold: true } }, 1));
q.push(cond(st, 'TEXT_CONTAINS', '✔', { textFormat: { foregroundColor: green, bold: true } }, 2));
q.push(cond([rng(12,13,15,16)], 'NUMBER_GREATER', '0', { textFormat: { foregroundColor: red, bold: true } }, 3));
q.push(cond([rng(16,26,10,11)], 'TEXT_CONTAINS', 'fechou', { textFormat: { foregroundColor: green, bold: true } }, 4));
q.push(cond([rng(16,26,10,11)], 'TEXT_CONTAINS', 'analisar', { textFormat: { foregroundColor: amb, bold: true } }, 5));
// larguras
const w = [140,75,130,70,80,80,18,160,120,105,85,80,70,18,135,145,115,105,55];
for (let i = 0; i < w.length; i++) q.push(colw(i, w[i]));
// validations (dropdowns)
const meses = [{ userEnteredValue: '(atual)' }];
for (let y = 2026; y <= 2027; y++) for (let m = 1; m <= 12; m++) { if (y === 2026 && m < 7) continue; meses.push({ userEnteredValue: y + '-' + String(m).padStart(2,'0') }); }
q.push({ setDataValidation: { range: rng(1,2,3,4), rule: { condition: { type: 'ONE_OF_LIST', values: meses }, showCustomUi: true, strict: true } } });
const etapas = ['(todas)','docs_enviados','processamento_matriz','assinatura_cliente','assinatura_diretoria','aguardando_ativacao','ativo','cancelado'].map(function(e){ return { userEnteredValue: e }; });
q.push({ setDataValidation: { range: rng(15,16,15,16), rule: { condition: { type: 'ONE_OF_LIST', values: etapas }, showCustomUi: true, strict: true } } });
// protecao
q.push({ addProtectedRange: { protectedRange: { range: { sheetId: D }, warningOnly: true, description: 'Painel gerado por formulas. Use apenas os dois filtros (Mes e Etapa).' } } });
return [{ json: { requests: q } }];
